import { createHash } from 'node:crypto';
import { open, lstat, realpath } from 'node:fs/promises';
import path from 'node:path';
import sax from 'sax';
import { inspectZipArchive, skillLimits } from './carb-skill-source.js';

/**
 * Output contracts used by the task runner and by the release smoke test.
 * Office files are intentionally checked as ZIP packages instead of being
 * opened by an installed Office application, so the check is deterministic
 * on clean machines and does not mutate the user's documents.
 */
export const ARTIFACT_SPECS = Object.freeze({
  pptx: { kind: 'pptx', label: 'PowerPoint 演示文稿', main: 'ppt/presentation.xml', root: 'presentation', part: /^ppt\/slides\/slide[^/]+\.xml$/u, partRoot: 'sld', open: '使用 Microsoft PowerPoint、WPS 演示或文件资源管理器双击打开。' },
  docx: { kind: 'docx', label: 'Word 文档', main: 'word/document.xml', root: 'document', open: '使用 Microsoft Word、WPS 文字或文件资源管理器双击打开。' },
  xlsx: { kind: 'xlsx', label: 'Excel 工作簿', main: 'xl/workbook.xml', root: 'workbook', part: /^xl\/worksheets\/sheet[^/]+\.xml$/u, partRoot: 'worksheet', open: '使用 Microsoft Excel、WPS 表格或文件资源管理器双击打开。' },
  py: { kind: 'py', label: 'Python 脚本', required: [], open: '使用 Python 运行，或使用 VS Code、PyCharm 等编辑器打开。' },
  md: { kind: 'md', label: 'Markdown 文档', required: [], open: '使用 Carb 预览、Typora、VS Code 或任意文本编辑器打开。' },
});

function extension(filename) {
  return path.extname(filename).slice(1).toLowerCase();
}

function utf8(bytes, filename) {
  try {
    const text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
    if (text.includes('\0')) throw new Error('NUL');
    return text;
  } catch { throw new Error(`产出文件不是有效 UTF-8 文本：${filename}`); }
}

function officePackage(bytes, spec, filename) {
  let entries;
  try { entries = inspectZipArchive(bytes); }
  catch (error) { throw new Error(`${spec.label}压缩包校验失败：${filename}（${error.message}）`); }
  const files = new Map(entries.filter(item => !item.directory).map(item => [item.parts.join('/'), item.content]));
  const parsed = new Map();
  const xml = (name, root) => {
    if (!files.has(name)) throw new Error(`${spec.label}缺少必要结构（${name}）：${filename}`);
    const text = utf8(files.get(name), name);
    // SAX verifies well-formed XML and namespace bindings without resolving
    // external entities. Office schema/layout checks remain a separate step.
    let documentRoot;
    const nodes = [];
    try {
      if (/<!DOCTYPE|<!ENTITY/iu.test(text)) throw new Error('Declarations are not allowed');
      const parser = sax.parser(true, { xmlns: true, strictEntities: true });
      parser.onopentag = node => { documentRoot ??= node; nodes.push(node); };
      parser.write(text).close();
      if (!documentRoot || (root && documentRoot.local !== root)) throw new Error('Unexpected document root');
      const namespaceFamily = { docx: 'wordprocessingml', pptx: 'presentationml', xlsx: 'spreadsheetml' }[spec.kind];
      const namespaces = root === 'Types' ? ['http://schemas.openxmlformats.org/package/2006/content-types']
        : root === 'Relationships' ? ['http://schemas.openxmlformats.org/package/2006/relationships']
        : root && (root === spec.root || root === spec.partRoot) ? [`http://schemas.openxmlformats.org/${namespaceFamily}/2006/main`, `http://purl.oclc.org/ooxml/${namespaceFamily}/main`] : undefined;
      if (namespaces && !namespaces.includes(documentRoot.uri)) throw new Error('Unexpected XML namespace');
    } catch { throw new Error(`${spec.label}的 XML 结构无效（${name}）：${filename}`); }
    parsed.set(name, nodes);
    return text;
  };
  const attribute = (node, name) => node.attributes[name]?.value;
  xml('[Content_Types].xml', 'Types');
  xml('_rels/.rels', 'Relationships');
  if (!parsed.get('[Content_Types].xml').some(node => node.local === 'Override' && attribute(node, 'PartName') === '/' + spec.main) ||
      !parsed.get('_rels/.rels').some(node => node.local === 'Relationship' && attribute(node, 'Type')?.endsWith('/officeDocument') && attribute(node, 'Target')?.replace(/^\//u, '') === spec.main && attribute(node, 'TargetMode') !== 'External'))
    throw new Error(`${spec.label}的文档类型或根关系无效：${filename}`);
  xml(spec.main, spec.root);
  if (spec.part) {
    const parts = [...files.keys()].filter(name => spec.part.test(name));
    if (!parts.length) throw new Error(`${spec.label}没有可用的页面或工作表：${filename}`);
    for (const name of parts) xml(name, spec.partRoot);
  }
  for (const name of files.keys()) {
    if (/\.(?:xml|rels)$/iu.test(name) && !parsed.has(name)) xml(name);
    if (!name.endsWith('.rels')) continue;
    const relationshipRoot = name === '_rels/.rels' ? '' : path.posix.dirname(path.posix.dirname(name));
    for (const node of parsed.get(name) ?? []) {
      if (node.local !== 'Relationship' || attribute(node, 'TargetMode') === 'External') continue;
      const target = attribute(node, 'Target');
      if (!target || target.includes('\\')) throw new Error(`${spec.label}包含无效的内部关系：${filename}`);
      let decoded;
      try { decoded = decodeURIComponent(target.split('#')[0]); } catch { throw new Error(`${spec.label}包含无效的内部关系：${filename}`); }
      if (!decoded) continue;
      const resolved = path.posix.normalize(decoded.startsWith('/') ? decoded.slice(1) : path.posix.join(relationshipRoot, decoded));
      if (resolved.startsWith('../') || !files.has(resolved)) throw new Error(`${spec.label}的内部关系指向不存在的文件（${resolved}）：${filename}`);
    }
  }
  return files.size;
}

function safeRelativePath(filename) {
  if (typeof filename !== 'string' || !filename.trim() || filename.includes('\0')) throw new Error('产出文件路径不能为空。');
  if (path.isAbsolute(filename) || path.win32.isAbsolute(filename) || /^[a-z]:/iu.test(filename)) throw new Error('产出文件必须位于当前项目内。');
  const normalized = filename.replaceAll('\\', '/');
  if (normalized.split('/').some(part => !part || part === '.' || part === '..' || /[\x00-\x1f\x7f:<>"|?*]/u.test(part) || /[. ]$/u.test(part))) throw new Error('产出文件路径不安全。');
  return normalized;
}

function digest(bytes) { return createHash('sha256').update(bytes).digest('hex'); }

function validateBytes(filename, bytes) {
  const kind = extension(filename);
  const spec = ARTIFACT_SPECS[kind];
  if (!spec) throw new Error(`不支持的产出文件类型：${filename}。支持 PPTX、DOCX、XLSX、PY 和 MD。`);
  if (!bytes.length) throw new Error(`产出文件为空：${filename}`);
  if (bytes.length > skillLimits.compressed) throw new Error(`产出文件超过 32 MB：${filename}`);
  if (kind === 'pptx' || kind === 'docx' || kind === 'xlsx') {
    const entries = officePackage(bytes, spec, filename);
    return { kind, label: spec.label, bytes: bytes.length, sha256: digest(bytes), entries, open: spec.open };
  }
  const text = utf8(bytes, filename);
  if (kind === 'md' && !text.trim()) throw new Error(`Markdown 文档为空：${filename}`);
  if (kind === 'py' && !text.trim()) throw new Error(`Python 脚本为空：${filename}`);
  return { kind, label: spec.label, bytes: bytes.length, sha256: digest(bytes), open: spec.open };
}

export async function verifyArtifactSet(workspacePath, filenames) {
  if (!Array.isArray(filenames) || filenames.length !== 5) throw new Error('产出验收必须一次提供 PPTX、DOCX、XLSX、PY、MD 五个文件。');
  const root = await realpath(workspacePath);
  const seenKinds = new Set();
  const records = [];
  for (const input of filenames) {
    const relative = safeRelativePath(input);
    const kind = extension(relative);
    if (seenKinds.has(kind)) throw new Error(`产出验收中重复出现 ${kind} 文件。`);
    seenKinds.add(kind);
    const absolute = path.resolve(root, relative);
    const contained = target => { const part = path.relative(root, target); return part && part !== '..' && !part.startsWith('..' + path.sep) && !path.isAbsolute(part); };
    if (!contained(absolute)) throw new Error('产出文件必须位于当前项目内。');
    let current = root;
    for (const part of relative.split('/')) {
      current = path.join(current, part);
      if ((await lstat(current)).isSymbolicLink()) throw new Error(`产出路径不能包含符号链接：${relative}`);
    }
    if (!contained(await realpath(absolute))) throw new Error('产出文件必须位于当前项目内。');
    const info = await lstat(absolute);
    if (!info.isFile() || info.nlink !== 1 || info.size > skillLimits.compressed) throw new Error(`产出路径必须是项目内独立的普通文件，且不超过 32 MB：${relative}`);
    const handle = await open(absolute, 'r');
    let bytes;
    try {
      const before = await handle.stat();
      if (!before.isFile() || before.nlink !== 1 || before.ino !== info.ino || before.dev !== info.dev || before.size !== info.size) throw new Error(`验收期间产出文件已变化：${relative}`);
      bytes = await handle.readFile();
      const after = await handle.stat();
      const latest = await lstat(absolute);
      if (after.size !== before.size || after.mtimeMs !== before.mtimeMs || after.ctimeMs !== before.ctimeMs || latest.ino !== before.ino || latest.dev !== before.dev || latest.isSymbolicLink() || !contained(await realpath(absolute))) throw new Error(`验收期间产出文件已变化：${relative}`);
    } finally { await handle.close(); }
    const record = validateBytes(relative, bytes);
    records.push({ path: relative, absolutePath: absolute, ...record });
  }
  for (const kind of Object.keys(ARTIFACT_SPECS)) if (!seenKinds.has(kind)) throw new Error(`缺少 ${ARTIFACT_SPECS[kind].label}（${kind}）。`);
  return { ok: true, count: records.length, records };
}

function linkPath(relative) {
  return relative.split('/').map(part => encodeURIComponent(part)).join('/');
}

export function artifactOutputReceipt(report, workspacePath, chinese = true) {
  const lines = [chinese ? '## 任务产出与验收' : '## Task outputs and verification', chinese ? `已完成 ${report.count} 个产出文件的结构验收。` : `${report.count} output files passed structural verification.`];
  for (const item of report.records) {
    const address = path.resolve(workspacePath, item.path);
    lines.push(`- [${item.path}](${linkPath(item.path)}) — ${item.label} · ${item.bytes} 字节 · SHA-256 \`${item.sha256}\``);
    lines.push(`  - ${chinese ? '地址' : 'Path'}：\`${address}\``);
    lines.push(`  - ${chinese ? '打开方式' : 'Open with'}：${item.open}`);
  }
  lines.push(chinese ? '以上链接可直接打开文件操作菜单；程序或脚本文件会引导在编辑器中打开，避免直接执行。' : 'Use the links to open file actions. Program and script files are opened in an editor instead of executed directly.');
  return lines.join('\n');
}

export function artifactTaskInstructions(chinese = true) {
  return chinese
    ? '任务结束前必须生成并验收一份 PPTX、一份 DOCX、一份 XLSX、一份 Python 脚本和一份 Markdown 文件。优先调用对应技能，再使用工作区工具生成文件；生成后调用 artifact_inspect 一次性校验五个路径，并在最终答复中分别说明结果、相对链接、绝对地址和打开方式。任何一个文件缺失、为空、结构无效或校验失败，都不得宣称任务完成。'
    : 'Before finishing, create and verify one PPTX, DOCX, XLSX, Python script and Markdown file. Use the relevant skills and workspace tools, then call artifact_inspect with all five paths. Report each result with a relative link, absolute path and opening method. If any file is missing, empty, structurally invalid or fails verification, do not claim the task is complete.';
}
